codeExamples.code:
// Blink status indicator for Rover Power Module
const int POWER_LED_PIN = 13;
const int BLINK_MS = 400;

void setup() {
  pinMode(POWER_LED_PIN, OUTPUT);
}

void loop() {
  digitalWrite(POWER_LED_PIN, HIGH);
  delay(BLINK_MS);
  digitalWrite(POWER_LED_PIN, LOW);
  delay(BLINK_MS);
}

